import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"أخلاقيات الزراعة وحدودها","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0019-修炼伦理与边界.md","filePath":"ar/0019-修炼伦理与边界.md"}'),e={name:"ar/0019-修炼伦理与边界.md"};function o(d,t,h,n,s,u){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="أخلاقيات-الزراعة-وحدودها" tabindex="-1">أخلاقيات الزراعة وحدودها <a class="header-anchor" href="#أخلاقيات-الزراعة-وحدودها" aria-label="Permalink to &quot;أخلاقيات الزراعة وحدودها&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>19</td></tr><tr><td>الوحدة</td><td>القوانين الكونية وأنظمة الزراعة</td></tr><tr><td>الكلمات المفتاحية</td><td>أخلاقيات الزراعة، الحدود، المحظورات، الخط الأخلاقي الأدنى، الفحص الأخلاقي</td></tr></tbody></table><h2 id="أولاً-تعريف-أخلاقيات-الزراعة-ومكانتها" tabindex="-1">أولاً: تعريف أخلاقيات الزراعة ومكانتها <a class="header-anchor" href="#أولاً-تعريف-أخلاقيات-الزراعة-ومكانتها" aria-label="Permalink to &quot;أولاً: تعريف أخلاقيات الزراعة ومكانتها&quot;">​</a></h2><p>أخلاقيات الزراعة هي مجموع القواعد الأخلاقية والقانونية في حضارة التكافل المرساة التي تضبط سلوك المزارعين وتحدد حدود الزراعة وتصون نظامها. في عصر الافتراس، كانت الزراعة تُعد «امتياز الأقوياء»، وكان المزارعون يلجؤون إلى كل الوسائل لرفع قوتهم — ابتلاع أصل الآخرين، واستعباد أرواحهم، ونهب مواردهم، وإجراء تجارب زراعة لاإنسانية وغيرها. هذه الثقافة الزراعية القائمة على «القوة أولاً والأخلاق لا شيء» هي أعمق جذور نظام الافتراس الروحية.</p><p>بعد قيام حضارة التكافل المرساة، جُعل بناء أخلاقيات الزراعة من أهم بنود بناء الحضارة الروحية. القضية الأساسية للأخلاقيات: «يجب أن يخضع اكتساب القوة واستخدامها للأخلاق». ترى الحضارة التكافلية أن الزراعة ليست شأناً شخصياً خالصاً، بل شأن عام يتعلق بالآخرين وبالحضارة وبالكون كله. فعلى المزارعين، سعياً لرفع قوتهم، احترام حقوق الآخرين وصيانة نظام الحضارة وحماية بيئة الكون. أخلاقيات الزراعة ليست قيداً على الزراعة، بل حارسة لها — تضمن سير الزراعة دائماً على طريق «التطور التكافلي» الصحيح دون الانزلاق إلى هاوية «الافتراس والتدمير».</p><p>تحتل أخلاقيات الزراعة مكانة سامية في النظام القانوني للحضارة التكافلية. يحدد الدستور التكافلي المبادئ الأساسية للأخلاقيات صراحةً؛ وتنشئ محكمة المراسي «محكمة أخلاقية» متخصصة للفصل في قضايا الأخلاقيات؛ وتشترط اعتماد مراتب جميع المزارعين المتقدمين اجتياز فحص أخلاقي. أخلاقيات الزراعة ليست «قيداً ليناً» اختيارياً، بل «قاعدة صارمة» ملزمة.</p><h2 id="ثانياً-المبادئ-الأساسية-لأخلاقيات-الزراعة" tabindex="-1">ثانياً: المبادئ الأساسية لأخلاقيات الزراعة <a class="header-anchor" href="#ثانياً-المبادئ-الأساسية-لأخلاقيات-الزراعة" aria-label="Permalink to &quot;ثانياً: المبادئ الأساسية لأخلاقيات الزراعة&quot;">​</a></h2><h3 id="_2-1-مبدأ-كرامة-الحياة" tabindex="-1">2.1 مبدأ كرامة الحياة <a class="header-anchor" href="#_2-1-مبدأ-كرامة-الحياة" aria-label="Permalink to &quot;2.1 مبدأ كرامة الحياة&quot;">​</a></h3><p>لكل كائن كرامة وقيمة لا تُنتهك، ولا يجوز أن يتم أي سلوك زراعي على حساب الإضرار بكرامة الحياة. ويشمل ذلك:</p><ul><li>منع اتخاذ كائنات أخرى «مادة» أو «أداة» للزراعة</li><li>منع التجارب الزراعية اللاإنسانية (كتشريح الأحياء وتعذيب الأرواح وغيرها)</li><li>منع استعباد إرادة الكائنات الأخرى الحرة أو التحكم بها</li><li>احترام حق كل كائن في اختيار مسار تطوره، ومنع إكراه الآخرين على الزراعة بطريقته</li></ul><h3 id="_2-2-مبدأ-مكافحة-الافتراس" tabindex="-1">2.2 مبدأ مكافحة الافتراس <a class="header-anchor" href="#_2-2-مبدأ-مكافحة-الافتراس" aria-label="Permalink to &quot;2.2 مبدأ مكافحة الافتراس&quot;">​</a></h3><p>يجب أن تقوم الزراعة على الدورة التكافلية، وألا تتخذ نهب الآخرين وسيلة. ويشمل ذلك:</p><ul><li>منع ابتلاع أو نهب أصل الكائنات الأخرى وطاقتها وحظها</li><li>منع رفع سرعة الزراعة أو مراتبها عبر الإضرار بالآخرين</li><li>منع احتكار موارد الزراعة لتحقيق مكاسب غير مشروعة</li><li>منع التذرع بـ«الضعيف فريسة القوي» للدفاع عن السلوكيات الافتراسية</li></ul><h3 id="_2-3-مبدأ-الموافقة-المستنيرة" tabindex="-1">2.3 مبدأ الموافقة المستنيرة <a class="header-anchor" href="#_2-3-مبدأ-الموافقة-المستنيرة" aria-label="Permalink to &quot;2.3 مبدأ الموافقة المستنيرة&quot;">​</a></h3><p>يجب أن تتم السلوكيات الزراعية المتعلقة بالآخرين (كالوراثة بين الأستاذ والتلميذ، والزراعة المزدوجة بين الشريكين، ومشاركة الطاقة، والتجارب الزراعية وغيرها) بشرط معرفة الطرف الآخر الكاملة وموافقته الطوعية. ويشمل ذلك:</p><ul><li>الإيضاح الكامل للطرف الآخر بمحتوى السلوك الزراعي ومخاطره وفوائده</li><li>ضمان قدرة الطرف الآخر الكاملة على الحكم المستقل، دون إكراه أو إغراء</li><li>حق الطرف الآخر في الانسحاب في أي وقت، ومنع إكراهه على الاستمرار</li><li>للأفراد دون السن أو غير مكتملي الأهلية العقلية، يمارس أولياؤهم حق الموافقة نيابة عنهم على أساس تقييم مهني</li></ul><h3 id="_2-4-مبدأ-الأضرار-الدنيا" tabindex="-1">2.4 مبدأ الأضرار الدنيا <a class="header-anchor" href="#_2-4-مبدأ-الأضرار-الدنيا" aria-label="Permalink to &quot;2.4 مبدأ الأضرار الدنيا&quot;">​</a></h3><p>يجب أن تتجنب السلوكيات الزراعية الإضرار بالآخرين والبيئة قدر الإمكان. وعندما يكون بعض التأثير حتمياً، يجب اختيار الطريقة الأقل ضرراً وتعويض الضرر الواقع تعويضاً معقولاً. ويشمل ذلك:</p><ul><li>إجراء التجارب الزراعية أولاً في فضاء العزل، لمنع انتشار المخاطر</li><li>إجراء زراعة القتال قدر الإمكان في ميادين زراعة مخصصة، وتجنب تدمير البيئة العامة</li><li>تنظيف وإصلاح تلوثات الطاقة والأضرار الفضائية الناتجة عن الزراعة في حينها</li><li>منع الأنشطة الزراعية عالية الخطورة في المناطق كثيفة السكان</li></ul><h3 id="_2-5-مبدأ-الصدق-وعدم-الخداع" tabindex="-1">2.5 مبدأ الصدق وعدم الخداع <a class="header-anchor" href="#_2-5-مبدأ-الصدق-وعدم-الخداع" aria-label="Permalink to &quot;2.5 مبدأ الصدق وعدم الخداع&quot;">​</a></h3><p>يجب أن يلتزم المزارعون بالصدق في الشؤون الزراعية، ومنع التزوير. ويشمل ذلك:</p><ul><li>منع تزوير المراتب الزراعية وقيم المساهمة ونتائج الاختبارات وغيرها</li><li>منع التزوير أو الانتحال في الخبرات الزراعية والنتائج البحثية</li><li>منع تقديم معلومات كاذبة في طلبات الموارد وإعلانات المشاريع</li><li>منع الاحتيال على موارد الآخرين الزراعية أو ثقتهم بوعود كاذبة</li></ul><h3 id="_2-6-مبدأ-تحمل-المسؤولية" tabindex="-1">2.6 مبدأ تحمل المسؤولية <a class="header-anchor" href="#_2-6-مبدأ-تحمل-المسؤولية" aria-label="Permalink to &quot;2.6 مبدأ تحمل المسؤولية&quot;">​</a></h3><p>كلما كبرت القوة كبرت المسؤولية. يجب على المزارعين المتقدمين تحمل مسؤوليات عامة تتناسب مع قوتهم. ويشمل ذلك:</p><ul><li>وجوب إرشاد المزارعين المبتدئين على من يبلغ مرتبة معينة</li><li>وجوب مشاركة المزارعين المتقدمين في الشؤون العامة كصيانة المراسي وحماية الحضارة</li><li>تحمل المزارعين مسؤولية عواقب سلوكياتهم الزراعية، دون تهرب</li><li>وجوب تقدم المزارعين المتقدمين عند مواجهة الحضارة للأزمات</li></ul><h2 id="ثالثاً-المحظورات-المطلقة-في-الزراعة" tabindex="-1">ثالثاً: المحظورات المطلقة في الزراعة <a class="header-anchor" href="#ثالثاً-المحظورات-المطلقة-في-الزراعة" aria-label="Permalink to &quot;ثالثاً: المحظورات المطلقة في الزراعة&quot;">​</a></h2><p>السلوكيات التالية من «المحظورات المطلقة» في الزراعة؛ لا يجوز لأي مزارع الاقتراب منها في أي حال، والمخالفون يعاقبون أقسى عقاب:</p><table tabindex="0"><thead><tr><th>نوع المحظور</th><th>السلوك المحدد</th><th>إجراءات العقاب</th></tr></thead><tbody><tr><td>نهب الأصل</td><td>ابتلاع أو نهب أصل الكائنات الأخرى أو نواتها الحيوية</td><td>إسقاط الزراعة، والسجن المؤبد، وإفناء الأصل في الحالات الخطيرة</td></tr><tr><td>استعباد الأرواح</td><td>تحويل كائنات أخرى إلى أدوات بالتحكم بالأرواح والاستعباد الروحي</td><td>إسقاط الزراعة، وإصلاح أخلاقي إجباري، والحرمان الدائم من حق الزراعة</td></tr><tr><td>الإبادة العرقية</td><td>ذبح أو إبادة منهجية لعرق ما بغرض الزراعة</td><td>المحاكمة العليا لمحكمة المراسي، والعقاب الأقصى</td></tr><tr><td>تدمير الأبعاد</td><td>تدمير بُعد كامل للحصول على موارد أو قوة</td><td>العقاب الأقصى، وتحمل كامل مسؤولية إصلاح البُعد</td></tr><tr><td>التجارب اللاإنسانية</td><td>إجراء تجارب زراعية لاإنسانية على كائنات عاقلة</td><td>إسقاط الزراعة، والسجن المؤبد، وإتلاف جميع النتائج البحثية</td></tr><tr><td>جريمة الزمن</td><td>استخدام قدرة الرجوع الزمني لتزوير تاريخ واسع أو قتل</td><td>العقاب الأقصى، والحرمان الدائم من القدرات الزمنية</td></tr><tr><td>تلويث القوانين</td><td>تلويث القوانين الأصلية للكون عمداً، إلحاقاً بضرر لا رجعة فيه بالكون كله</td><td>العقاب الأقصى، وتنفيذ تنقية القوانين من أعلى هيئة في الحضارة</td></tr></tbody></table><p>يجسد وضع المحظورات المطلقة موقف الحضارة التكافلية الثابت من الخط الأخلاقي الأدنى للزراعة. لا «مناطق رمادية» لهذه المحظورات ولا «ظروف مخففة»؛ أي سلوك يمس المحظورات المطلقة يعاقب أقسى عقاب.</p><h2 id="رابعاً-المناطق-الرمادية-في-أخلاقيات-الزراعة-ومبادئ-معالجتها" tabindex="-1">رابعاً: المناطق الرمادية في أخلاقيات الزراعة ومبادئ معالجتها <a class="header-anchor" href="#رابعاً-المناطق-الرمادية-في-أخلاقيات-الزراعة-ومبادئ-معالجتها" aria-label="Permalink to &quot;رابعاً: المناطق الرمادية في أخلاقيات الزراعة ومبادئ معالجتها&quot;">​</a></h2><p>إلى جانب المحظورات الواضحة، توجد في الأخلاقيات بعض «المناطق الرمادية» — وهي سلوكيات ليست في ذاتها خيراً محضاً أو شراً محضاً، إذ تحدد طبيعتها الأخلاقية بالسياق والدافع والأسلوب والعواقب المحددة. وللمناطق الرمادية، تعتمد الحضارة التكافلية مبادئ المعالجة التالية:</p><h3 id="_4-1-المناطق-الرمادية-الشائعة" tabindex="-1">4.1 المناطق الرمادية الشائعة <a class="header-anchor" href="#_4-1-المناطق-الرمادية-الشائعة" aria-label="Permalink to &quot;4.1 المناطق الرمادية الشائعة&quot;">​</a></h3><ul><li><strong>الأضرار في زراعة القتال</strong>: قد يؤذي المزارعون بعضهم في تدريب النزال؛ فمشروعية هذا الضرر تعتمد على موافقة الطرفين المستنيرة وعلى كون الضرر ضمن نطاق معقول</li><li><strong>التنافس على الموارد</strong>: مشروعية التنافس بين المزارعين على الموارد النادرة تعتمد على عدالة أسلوب التنافس ومراعاة قواعد مكافحة الاحتكار</li><li><strong>عدم توازن القوة في علاقة الأستاذ بالتلميذ</strong>: يوجد عدم توازن طبيعي بينهما؛ ويحتاج الحكم على إساءة الأستاذ للسلطة إلى تقييم محدد</li><li><strong>تحمل المخاطر في الزراعة</strong>: بعض الطرائق الزراعية عالية الخطورة بطبيعتها؛ ومشروعية تحمل المزارع المخاطر طوعاً تحتاج لتقييم المعرفة الكاملة بالمخاطر ووجود البدائل</li><li><strong>التعاون الزراعي بين الأعراق</strong>: قد يشمل التعاون بين الأعراق اختلافات ثقافية وعدم توازن قوة، ويحتاج إلى تقييم محدد</li></ul><h3 id="_4-2-مبادئ-المعالجة" tabindex="-1">4.2 مبادئ المعالجة <a class="header-anchor" href="#_4-2-مبادئ-المعالجة" aria-label="Permalink to &quot;4.2 مبادئ المعالجة&quot;">​</a></h3><p>للمسائل الأخلاقية في المناطق الرمادية، تعتمد الحضارة التكافلية أسلوب «تحليل السياق المحدد + تقييم اللجنة الأخلاقية + الاسترشاد بالسوابق»:</p><ol><li><strong>تحليل السياق المحدد</strong>: بلا «مقاس واحد للجميع»، حكم شامل حسب السياق والدافع والأسلوب والعواقب المحددة</li><li><strong>تقييم اللجنة الأخلاقية</strong>: للمسائل الأخلاقية المعقدة، تُحال إلى «اللجنة الأخلاقية» التابعة لمحكمة المراسي للتقييم المهني</li><li><strong>الاسترشاد بالسوابق</strong>: تشكل نتائج تقييم اللجنة الأخلاقية سوابق، تُرشد القضايا المماثلة اللاحقة</li><li><strong>الأولوية للتعليم</strong>: للسلوكيات غير السليمة في المناطق الرمادية، يُقدَّم التعليم والتقويم على العقوبات القاسية المباشرة</li><li><strong>التعديل الديناميكي</strong>: مع تطور الحضارة وتعمق الفهم الأخلاقي، يمكن تعديل معايير الحكم على المناطق الرمادية ديناميكياً</li></ol><h2 id="خامساً-تعليم-أخلاقيات-الزراعة-واستبطانها" tabindex="-1">خامساً: تعليم أخلاقيات الزراعة واستبطانها <a class="header-anchor" href="#خامساً-تعليم-أخلاقيات-الزراعة-واستبطانها" aria-label="Permalink to &quot;خامساً: تعليم أخلاقيات الزراعة واستبطانها&quot;">​</a></h2><p>لا يمكن صيانة الأخلاقيات بالعقوبات والرقابة الخارجية وحدها؛ بل تحتاج أكثر إلى تقبل المزارعين لها واستبطانها من أعماقهم. أنشأت الحضارة التكافلية منظومة تعليم أخلاقي منهجية:</p><h3 id="_5-1-التعليم-الأساسي" tabindex="-1">5.1 التعليم الأساسي <a class="header-anchor" href="#_5-1-التعليم-الأساسي" aria-label="Permalink to &quot;5.1 التعليم الأساسي&quot;">​</a></h3><ul><li>الأخلاقيات مادة إلزامية لكل المزارعين، ويبدأ التعليم الأخلاقي المنهجي من مرحلة الإحساس بالأصل</li><li>يشمل المحتوى المبادئ الأخلاقية وقوائم المحظورات وتحليل الحالات ومحاكاة المواقف وغيرها</li><li>تشمل الأساليب التدريس الصفي ومناقشة الحالات ولعب الأدوار وقدوة الأساتذة القولية والفعلية وغيرها</li></ul><h3 id="_5-2-التعليم-المتقدم" tabindex="-1">5.2 التعليم المتقدم <a class="header-anchor" href="#_5-2-التعليم-المتقدم" aria-label="Permalink to &quot;5.2 التعليم المتقدم&quot;">​</a></h3><ul><li>مع ارتفاع مراتب المزارعين، يرتفع عمق التعليم الأخلاقي واتساعه تبعاً لذلك</li><li>يحتاج المزارعون المتقدمون إلى تعلم مسائل أخلاقية أكثر تعقيداً (كأخلاقيات ما بين الأبعاد وأخلاقيات الزمن وأخلاقيات خلق العوالم)</li><li>يجب على المزارعين فوق مرتبة داو الأصل اجتياز «الاختبار الأخلاقي العالي» لمواصلة رفع مراتبهم</li></ul><h3 id="_5-3-التطبيق-والاستبطان" tabindex="-1">5.3 التطبيق والاستبطان <a class="header-anchor" href="#_5-3-التطبيق-والاستبطان" aria-label="Permalink to &quot;5.3 التطبيق والاستبطان&quot;">​</a></h3><ul><li>تشجيع المزارعين على ممارسة المبادئ الأخلاقية في زراعتهم اليومية، وتحويل المتطلبات الأخلاقية إلى عادات سلوكية واعية</li><li>إنشاء نظام اختيار «القدوات الأخلاقية»، وتكريم المزارعين المتميزين في الأخلاقيات الزراعية</li><li>وجوب نقل الأساتذة الروح الأخلاقية إلى جانب تعليم المهارات الزراعية، تحقيقاً لـ«نقل الداو والفن معاً»</li></ul><h2 id="سادساً-إشراف-أخلاقيات-الزراعة-وتنفيذها" tabindex="-1">سادساً: إشراف أخلاقيات الزراعة وتنفيذها <a class="header-anchor" href="#سادساً-إشراف-أخلاقيات-الزراعة-وتنفيذها" aria-label="Permalink to &quot;سادساً: إشراف أخلاقيات الزراعة وتنفيذها&quot;">​</a></h2><h3 id="_6-1-آليات-الإشراف" tabindex="-1">6.1 آليات الإشراف <a class="header-anchor" href="#_6-1-آليات-الإشراف" aria-label="Permalink to &quot;6.1 آليات الإشراف&quot;">​</a></h3><ul><li><strong>مراقبة شبكة المراسي</strong>: تراقب الشبكة سلوكيات المزارعين الزراعية مراقبة متواصلة، وتنبه مبكراً للانتهاكات الأخلاقية المشتبه بها</li><li><strong>نظام البلاغ الأخلاقي</strong>: يمكن لأي كائن إبلاغ المحكمة الأخلاقية التابعة لمحكمة المراسي بانتهاكات الأخلاقيات، ويُحمى المبلغون</li><li><strong>التقييم الأخلاقي الدوري</strong>: يخضع المزارعون البالغون مرتبة قانون الأصل فما فوق لتقييم أخلاقي سنوي، وتُسجل نتائجه في ملفاتهم الزراعية الشخصية</li><li><strong>إشراف المنظمات الاجتماعية</strong>: تشجيع منظمات المزارعين والمجتمعات العرقية على الإشراف الداخلي على أخلاقيات أعضائها</li></ul><h3 id="_6-2-آليات-التنفيذ" tabindex="-1">6.2 آليات التنفيذ <a class="header-anchor" href="#_6-2-آليات-التنفيذ" aria-label="Permalink to &quot;6.2 آليات التنفيذ&quot;">​</a></h3><ul><li><strong>المحكمة الأخلاقية</strong>: تنشئ محكمة المراسي محكمة أخلاقية متخصصة للفصل في قضايا الأخلاقيات الزراعية</li><li><strong>العقوبات المتدرجة</strong>: حسب خطورة الانتهاك الأخلاقي، تتراوح العقوبات من الإنذار والغرامة وخصم قيم المساهمة وتقييد صلاحيات الزراعة وإسقاط الزراعة إلى السجن المؤبد والعقاب الأقصى</li><li><strong>الإصلاح الأخلاقي</strong>: للمخالفين الراغبين في التوبة، يمكن إجراء إصلاح أخلاقي مع العقوبة، وبعد نجاحه تُستعاد بعض الحقوق جزئياً</li><li><strong>سجل السوابق</strong>: تُدوَّن مخالفات الأخلاقيات الزراعية في الملف الشخصي بشكل دائم، مؤثرةً في اعتماد المراتب وتوزيع الموارد وطلبات المناصب العامة لاحقاً</li></ul><h2 id="سابعاً-التوسع-الديناميكي-لحدود-الزراعة" tabindex="-1">سابعاً: التوسع الديناميكي لحدود الزراعة <a class="header-anchor" href="#سابعاً-التوسع-الديناميكي-لحدود-الزراعة" aria-label="Permalink to &quot;سابعاً: التوسع الديناميكي لحدود الزراعة&quot;">​</a></h2><p>أخلاقيات الزراعة وحدودها ليست عقائد جامدة، بل قواعد حية تتعدل ديناميكياً مع تطور الحضارة وتقدم التقنيات وتعمق الفهم. أنشأت الحضارة التكافلية آلية التوسع الديناميكي لحدود الزراعة:</p><ol><li><strong>التقييم الأخلاقي للتقنيات الجديدة</strong>: كلما ظهرت تقنية زراعة جديدة أو تطبيق قانون جديد، يُجرى تقييم أخلاقي أولاً، ولا يُعمَّم إلا بعد اجتيازه</li><li><strong>البحث الأخلاقي للمشاهد الجديدة</strong>: عند دخول الحضارة مراحل تطور جديدة (كعصر ما بين الأبعاد والعصر النجمي)، تُنظم بحوث أخلاقية خاصة لوضع قواعد أخلاقية مناسبة للمشاهد الجديدة</li><li><strong>التنقيح الدوري للقواعد الأخلاقية</strong>: تُنقح القواعد المحددة للأخلاقيات كل خمسين عاماً، ويستجمع التنقيح آراء جميع الكائنات على نطاق واسع</li><li><strong>تراكم السوابق الأخلاقية باستمرار</strong>: تشكل أحكام المحكمة الأخلاقية سوابق، تُثري وتُدقق محتوى الأخلاقيات المحدد باستمرار</li></ol><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>أخلاقيات الزراعة وحدودها هي الركيزة الأساسية للحضارة الروحية لحضارة التكافل المرساة. إنها تجيب عن سؤال جوهري: «أي إنسان ينبغي أن يصبح المزارع؟» جواب الحضارة التكافلية: يجب أن يصبح المزارع إنساناً ذا قوة، والأهم ذا أخلاق؛ وإنساناً يتحد فيه التطور الشخصي بتكافل عشرة آلاف عرق؛ وإنساناً يسعى للقوة لكن لا تستعبده القوة أبداً. أخلاقيات الزراعة ليست قيداً على القوة، بل سماها بها — تضمن أن تخدم القوة دائماً كرامة الحياة وتقدم الحضارة، وألا تصبح أداة تدمير ونهب. في كونٍ تستطيع فيه القوة نقل الجبال والبحار، وخلق العوالم وتدميرها، تُعد أخلاقيات الزراعة آخر خطوط الدفاع عن خط الحضارة الأدنى وأهمها.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (الأطروحات الأساسية لمكافحة الافتراس)</li><li>17-位面至高强者标准 (معايير قوى الأبعاد العليا)</li><li>48-司法体系与裁决机制 (النظام القضائي وآلية الحكم)</li></ul>',56)])])}const _=a(e,[["render",o]]);export{b as __pageData,_ as default};
